import React, { useState } from 'react';
import { 
  UserIcon, MapPinIcon, PhoneIcon, TruckIcon, 
  ClockIcon, GiftIcon, CheckCircleIcon, 
  HomeIcon, ShoppingBagIcon 
} from '@heroicons/react/24/outline';

const Orders = () => {
  const [order, setOrder] = useState({
    orderID: "ORD-2026-991",
    status: "Pending",
    paymentType: "Cash on Delivery",
    totalAmount: 5250.00,
    items: [
      { name: "Keells Sugar 1kg", quantity: 2, unitPriceAtSale: 250, isPacked: false },
      { name: "Anchor Milk Powder 400g", quantity: 1, unitPriceAtSale: 1100, isPacked: false },
      { name: "Munchee Super Cream Cracker", quantity: 3, unitPriceAtSale: 180, isPacked: false }
    ],
    customer: {
      name: "Saman Kumara",
      phoneNumber: "071-2345678",
      address: { houseNumber: "No. 45/A", street: "Temple Road", landMark: "Near Clock Tower" }
    }
  });

  const statuses = ['Pending', 'Packing', 'Out for Delivery', 'Delivered'];
  const currentIdx = statuses.indexOf(order.status);

  const advanceStatus = () => {
    if (currentIdx < statuses.length - 1) {
      setOrder({ ...order, status: statuses[currentIdx + 1] });
    }
  };

  const togglePacked = (idx) => {
    const newItems = [...order.items];
    newItems[idx].isPacked = !newItems[idx].isPacked;
    setOrder({ ...order, items: newItems });
  };

  return (
    <div className="flex min-h-screen bg-gray-100 font-sans">
      {/* 1. SIDEBAR: Layout එකේ වර්ණ සංකලනය අනුව */}
      <aside className="w-64 bg-gradient-to-b from-blue-700 to-blue-900 text-white flex flex-col shadow-2xl z-40 fixed h-full md:relative">
        <div className="p-6 border-b border-blue-600">
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <HomeIcon className="w-8 h-8 text-yellow-400" />
            BigMart
          </h1>
          <p className="text-sm text-blue-200 mt-1 italic uppercase tracking-widest font-semibold">Delivery System</p>
        </div>

        <nav className="mt-6 flex-1">
          {/* Active Link Styling */}
          <div className="flex items-center gap-3 px-6 py-4 bg-blue-600 border-r-4 border-yellow-400 transition-all">
            <TruckIcon className="w-6 h-6 text-yellow-400" />
            <span className="font-bold text-lg">Active Orders</span>
          </div>
          
          <div className="flex items-center gap-3 px-6 py-4 hover:bg-blue-600/30 text-blue-100 transition-colors cursor-not-allowed">
            <ShoppingBagIcon className="w-5 h-5" />
            <span className="text-sm">Order History</span>
          </div>
        </nav>
      </aside>

      {/* 2. MAIN CONTENT AREA */}
      <div className="flex-1 flex flex-col">
        {/* HEADER: Layout එකට ගැලපෙන්න */}
        <header className="bg-white shadow-md p-8 border-b border-gray-200">
          <h2 className="text-3xl font-bold text-gray-900 uppercase tracking-tight">Procurement & Delivery</h2>
          <p className="text-gray-600 mt-1">Efficiently manage your neighborhood inventory and order status</p>
        </header>

        {/* PAGE CONTENT */}
        <main className="p-8">
          <div className="max-w-5xl mx-auto">
            
            {/* ORDER CARD */}
            <div className="bg-white rounded-2xl shadow-lg border border-gray-100 overflow-hidden">
              <div className="bg-gray-50 p-6 border-b flex justify-between items-center">
                <div>
                  <h3 className="text-xl font-black text-blue-900 tracking-wide">{order.orderID}</h3>
                  <p className="text-sm text-gray-500 font-medium">Customer: {order.customer.name}</p>
                </div>
                <div className="flex flex-col items-end">
                   <span className="bg-blue-600 text-white px-6 py-1.5 rounded-full text-xs font-black uppercase tracking-widest shadow-md">
                    {order.status}
                  </span>
                </div>
              </div>

              <div className="p-8">
                {/* 3. STEPPER: Professional Blue Colors */}
                <div className="flex justify-between mb-12 relative px-4">
                  <div className="absolute top-5 left-0 w-full h-1 bg-gray-200 -z-0"></div>
                  <div 
                    className="absolute top-5 left-0 h-1 bg-blue-600 transition-all duration-500 ease-out"
                    style={{ width: `${(currentIdx / 3) * 100}%` }}
                  ></div>

                  {statuses.map((s, i) => (
                    <div key={s} className="z-10 flex flex-col items-center">
                      <div className={`w-12 h-12 rounded-full flex items-center justify-center transition-all duration-300 border-4 shadow-sm ${
                        i <= currentIdx ? 'bg-blue-600 border-blue-100 text-white scale-110' : 'bg-white border-gray-200 text-gray-400'
                      }`}>
                         {i === 0 && <ClockIcon className="w-6 h-6"/>}
                         {i === 1 && <GiftIcon className="w-6 h-6"/>}
                         {i === 2 && <TruckIcon className="w-6 h-6"/>}
                         {i === 3 && <CheckCircleIcon className="w-6 h-6"/>}
                      </div>
                      <span className={`text-xs font-black mt-3 uppercase tracking-tighter ${i <= currentIdx ? 'text-blue-800' : 'text-gray-400'}`}>{s}</span>
                    </div>
                  ))}
                </div>

                {/* 4. DETAILS GRID */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {/* Packing List */}
                  <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                    <div className="bg-blue-50 px-5 py-3 border-b border-blue-100">
                       <h4 className="font-bold text-blue-900 flex items-center gap-2">
                         <ShoppingBagIcon className="w-5 h-5" /> Packing Checklist
                       </h4>
                    </div>
                    <div className="p-5">
                      {order.items.map((item, i) => (
                        <div key={i} className="flex items-center space-x-4 mb-4 group cursor-pointer" onClick={() => togglePacked(i)}>
                           <div className={`w-6 h-6 rounded border-2 flex items-center justify-center transition-colors ${item.isPacked ? 'bg-green-500 border-green-500' : 'bg-white border-gray-300 group-hover:border-blue-500'}`}>
                             {item.isPacked && <CheckCircleIcon className="w-5 h-5 text-white" />}
                           </div>
                           <span className={`flex-1 font-semibold ${item.isPacked ? 'line-through text-gray-400' : 'text-gray-700'}`}>
                             {item.name} <span className="text-xs text-gray-400 font-normal ml-1">x {item.quantity}</span>
                           </span>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Destination Info */}
                  <div className="bg-gradient-to-br from-gray-50 to-white rounded-xl border-2 border-dashed border-gray-200 p-6 relative">
                     <h4 className="font-bold mb-4 text-gray-800 flex items-center gap-2">
                       <MapPinIcon className="w-6 h-6 text-blue-600" /> Delivery Destination
                     </h4>
                     <div className="space-y-4">
                        <div className="flex items-start gap-3">
                          <UserIcon className="w-5 h-5 text-gray-400 mt-0.5" />
                          <div>
                            <p className="text-sm font-black text-gray-800 uppercase">{order.customer.name}</p>
                            <p className="text-xs font-bold text-blue-600 flex items-center gap-1 mt-1">
                              <PhoneIcon className="w-3 h-3" /> {order.customer.phoneNumber}
                            </p>
                          </div>
                        </div>
                        <div className="bg-white p-4 rounded-lg shadow-inner border border-gray-100">
                           <p className="text-sm font-semibold text-gray-700 leading-relaxed">
                            {order.customer.address.houseNumber}, {order.customer.address.street}
                           </p>
                           <p className="text-xs text-yellow-600 font-bold mt-2 uppercase tracking-tight">
                            Landmark: {order.customer.address.landMark}
                           </p>
                        </div>
                     </div>
                  </div>
                </div>

                {/* 5. ACTION BUTTON: Professional & Bold */}
                {currentIdx < 3 && (
                  <button 
                    onClick={advanceStatus} 
                    className="mt-10 w-full bg-gradient-to-r from-blue-700 to-blue-800 hover:from-blue-800 hover:to-blue-900 text-white py-5 rounded-2xl font-black text-xl transition-all shadow-xl hover:shadow-2xl active:scale-95 flex items-center justify-center gap-3 group"
                  >
                    <span>ADVANCE TO {statuses[currentIdx+1].toUpperCase()}</span>
                    <TruckIcon className="w-6 h-6 group-hover:translate-x-2 transition-transform" />
                  </button>
                )}
              </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default Orders;
